    "description": "好管道，从内到外都讲究。今天揭秘玻璃钢管道的四层结构： 玻璃钢管道内部结构图 ①内表层又叫内衬层。它具有防渗防腐的作用，可以直接隔绝输送介质的侵蚀。它的厚度根据管道直径大小和压力高低计算一般为1.5～2.5mm。 ②过渡层。它的作用主要是缓冲内外压力，并防止毛细管现象发生。这一层主要是由短切毡 + 75±5%的树脂组成。 ③结构层（含夹砂层）。它是产品强度的关键。为了提高管道刚度加入了石英砂在该层中，这层也叫做夹砂层。 结构层由高强度玻…",
    "content": "好管道，从内到外都讲究。今天揭秘玻璃钢管道的四层结构： 玻璃钢管道内部结构图 ①内表层又叫内衬层。 它具有防渗防腐的作用，可以直接隔绝输送介质的侵蚀。它的厚度根据管道直径大小和压力高低计算一般为1.5～2.5mm。 ②过渡层。 它的作用主要是缓冲内外压力，并防止毛细管现象发生。这一层主要是由短切毡 + 75±5%的树脂组成。 ③结构层（含夹砂层）。 它是产品强度的关键。为了提高管道刚度加入了石英砂在该层中，这层也叫做夹砂层。 结构层由高强度玻璃纤维缠绕，紧紧包裹夹砂层，挡得住高压和地基沉降。 ④外保护层。 在该层中…"
