    "description": "新华社上海7月31日电（记者彭韵佳、龚雯）7月31日，第12批国家组织药品集采将在上海开标，投标企业7时30分开始陆续入场递交报价材料。本次集采共纳入65种药品，覆盖抗感染、抗肿瘤、抗血栓、降血糖、降血压、降血脂、风湿免疫、消炎镇痛等领域常用药品。 记者在开标现场看到，中国银行、中国出口信用保险公司、招商银行、浦发银行、上海银行、中国药品价格登记系统等机构，为投标企业介绍和提供“集采贷”“追溯码贷”“药品价格登记”等金融支持服务。",
    "content": "新华社上海7月31日电（记者彭韵佳、龚雯）7月31日，第12批国家组织药品集采将在上海开标，投标企业7时30分开始陆续入场递交报价材料。本次集采共纳入65种药品，覆盖抗感染、抗肿瘤、抗血栓、降血糖、降血压、降血脂、风湿免疫、消炎镇痛等领域常用药品。 记者在开标现场看到，中国银行、中国出口信用保险公司、招商银行、浦发银行、上海银行、中国药品价格登记系统等机构，为投标企业介绍和提供“集采贷”“追溯码贷”“药品价格登记”等金融支持服务。"
