    "description": "36氪获悉，7月30日，CPE源峰与欧洲私募股权机构Jacobs Capital正式签署股权购买协议，收购Mammut Sports Group AG（下称“猛犸象”）。本次交易尚需履行常规监管审批程序并满足相关交割条件，预计将于未来数月内完成交割。交易的具体财务细节未予披露。猛犸象创立于1862年，总部位于瑞士，是高端户外品牌之一。",
    "content": "36氪获悉，7月30日，CPE源峰与欧洲私募股权机构Jacobs Capital正式签署股权购买协议，收购Mammut Sports Group AG（下称“猛犸象”）。本次交易尚需履行常规监管审批程序并满足相关交割条件，预计将于未来数月内完成交割。交易的具体财务细节未予披露。猛犸象创立于1862年，总部位于瑞士，是高端户外品牌之一。"
