    "description": "8月1日，一个标注着人民军队光荣与梦想的日子。 岁岁“八一”，今又“八一”。中国人民解放军将迎来99岁生日。 99年风卷战旗红，99载热血铸忠诚。一面军旗，染红百年风雨；一腔军魂，铸就万里山河。鲜红的八一军旗，承载着一支军队的峥嵘岁月，镌刻着一个民族的不屈脊梁，见证着从建军之始到强军兴军的壮阔征程。 从南昌城头惊雷破晓、点燃武装革命星火，到新时代强军浪潮奔涌向前、铁甲雄师阔步前行，一代代革命军人弘扬光荣传统、赓续红色血脉，矢志强军备战、…",
