    "description": "“大师”，是对在相关领域有很深造诣从业者的褒奖，是承载行业沉淀、作品口碑、同行认可的稀缺称谓。但近年来，这个称号被逐渐滥用。茶叶、玉石、古玩、烹饪、养生等诸多行业，“批量”催生各类“大师”，满墙的证书、密集的头衔、浮夸的称号，“大师”称谓正在经历一场无声的贬值。 乱象滋生的原因不难理解。对从业者而言，普通匠人的作品卖不上价，而一旦贴上“大师”标签，便能迅速抬高身价，成为博取市场信任的金字招牌。对消费者而言，市场信息不对称普遍存在，消费者…",
    "content": "“大师”，是对在相关领域有很深造诣从业者的褒奖，是承载行业沉淀、作品口碑、同行认可的稀缺称谓。但近年来，这个称号被逐渐滥用。茶叶、玉石、古玩、烹饪、养生等诸多行业，“批量”催生各类“大师”，满墙的证书、密集的头衔、浮夸的称号，“大师”称谓正在经历一场无声的贬值。 乱象滋生的原因不难理解。对从业者而言，普通匠人的作品卖不上价，而一旦贴上“大师”标签，便能迅速抬高身价，成为博取市场信任的金字招牌。对消费者而言，市场信息不对称普遍存在，消费者出于对“权威认证”的信任，往往倾向于为“大师”出品买单。对组织者来说，各类评选有…"
