    "content": "30/07/2026 - 23:12 欧盟周四（7月30日）宣布启动一项大型招标案，预计吸引300亿欧元投资，兴建欧洲首批7座“人工智能超级工厂”，提供庞大运算能力，以期缩小欧洲在人工智能领域与美国和中国的差距。 欧盟执委会负责数位事务的副主席维尔库宁（Henna Virkkunen）周四表示，启动这项招标，是朝打造欧洲“人工智能大陆”雄心计划迈出的“重大一步”。她强调，建立如此庞大的电脑运算能力，是一项“战略需要”。 这项招标将由法国、德国、意大利和西班牙等18个欧盟成员国共同出资，投标期限至今年11月，目标是兴…"
