    "content": "欧足联发布声明 当地时间7月30日，欧洲足球管理机构欧足联及其55个成员国投票决定“抵制所有国际足联赛事”。 欧足联在一份声明中表示：“我们一致且明确拒绝国际足联提出的‘将世界杯及其他国际足联赛事的所有权权益转让给私人投资者’的提案。”声明说，若这些提案依然存在，任何欧足联下属球队都不会参加任何国际足联赛事，除非该提案被彻底放弃，且国际足联作出具有约束力的保证，承诺永不再将其治理权或赛事向私有资本开放。 欧足联强调，“世界杯并非商品，不能被视为投资产品，更不能拱手让予私人投资者。” 国际足联主席因凡蒂诺的计划旨在成…"
