    "content": "以色列第12频道电视台30日晚援引美方消息人士的话说，巴勒斯坦伊斯兰抵抗运动（哈马斯）或“很快”签署逐步解除武装的协议。 报道称，这项解除武装“路线图”由美国发起的所谓“和平委员会”提出，要求哈马斯在6至8个月内交出所有武器。巴勒斯坦技术官僚政府将逐步接管加沙地带部分地区，并核查这些地区是否还有武器。根据计划，哈马斯还将交出其隧道、武器工厂和仓库地图，交出的武器将由新的技术官僚政府和国际稳定部队保管。 报道称，根据协议，哈马斯成员将获得“赦免”，可继续留在加沙地带。以色列国防军将在协议签署后撤回至“黄线”，即以军根…"
