    "content": "新华社德黑兰7月30日电（记者陈霄 沙达提）伊朗外交部发言人巴加埃30日晚在社交媒体发文，谴责美国当天凌晨袭击伊朗南部格什姆岛居民区，造成一个五口之家中的父母及其两岁孩子死亡。 巴加埃说，此次袭击导致多栋民宅受损，出租车司机凯撒·贾法里、其妻子扎赫拉·贾法里及两岁儿子西纳遇难。 巴加埃称，此类行为令人联想到极端组织“伊斯兰国”的恐怖主义行径。他表示，此举不会给袭击者带来所谓“力量和信誉”，只会使伊朗人民更加坚定、更加团结地维护国家和自身权益。"
