    "content": "新华社华沙7月30日电（记者杨钰晨）波兰国防部国务秘书采扎雷·托姆奇克30日表示，波方已确认当天凌晨侵入波兰领空并坠落在该国东部卢布林省塔纳瓦－科洛尼亚附近的是一枚俄制Kh-101导弹。 托姆奇克在接受波兰媒体采访时说，该型导弹具备携带核弹头能力，是一种非常危险的巡航导弹。 他补充说，目前尚不清楚这枚导弹是否蓄意瞄准波兰。 波兰总理唐纳德·图斯克当天下午表示，该导弹坠落在无人区，并未造成人员伤亡。 截至记者发稿，俄方尚未对此作出回应。 波兰武装部队作战司令部30日稍早时通报说，当天凌晨3时40分，波军雷达在该国领空…"
