    "content": "30/07/2026 - 22:13 美国白宫30日表示，根据中央情报局（CIA）、国家安全局（NSA）、国土安全部（DHS）及国家情报总监办公室（ODNI）共同审核的最新事实说明，中国多年来透过购买、窃取及黑客入侵等方式，搜集约2.2亿笔美国选民登记资料，相关行为构成对美国选举的干预。 白宫本周四指出，中方取得的资料除公开可查询的选民资讯外，也包括部分非公开资料，情报显示中国多年来持续搜集并分析美国选民资讯。美方表示，目前仍无法确认究竟有多少资料是透过黑客攻击取得，又有多少来自合法购买或其他来源。 一名美国政府官…"
