    "content": "30/07/2026 - 19:27 法国、西班牙预料山火暂息，而欧洲其他地区又爆发新火情，其中希腊南部克里特岛火情严重。 法国西南部大火开始平息，参与扑救的消防员、军人及林业人员开始感到一丝乐观。截至周四上午，火势“仍处于稳定状态”，过火面积约为4.2万公顷；随着天气条件转好，22万名撤离人员有望很快恢复正常生活。 西班牙当局周四宣布，马德里地区的火灾已经数日没有出现蔓延，且“几乎已无明火”，西班牙政府解除了国家紧急状态，这再次表明面对这场史无前例的大火，局势正在好转。 希腊 希腊克里特岛正在发生火灾。据当局称，…"
