    "content": "新华社联合国7月30日电（记者尚绪谦）联合国安理会30日就下一任秘书长遴选举行首轮意向性投票。 安理会当月轮值主席、刚果（金）常驻联合国代表泽农·穆孔戈·恩盖在投票结束后说，意向性投票结果不对外公布，将通过候选人推举国通知各候选人。 目前下任联合国秘书长7位候选人分别为：智利前总统巴切莱特、来自厄瓜多尔的联大前主席埃斯皮诺萨、来自阿根廷的现任国际原子能机构总干事格罗西、来自哥斯达黎加的现任联合国贸易和发展会议秘书长格林斯潘、来自乌干达的联合国前副秘书长奥拉拉·奥通努、圭亚那常驻联合国代表罗德里格斯－伯基特、塞内加尔…"
