    "author": "李姝莛,殷家捷,金剑",
    "description": "7月30日，正在合肥参加2026中国网络文学论坛的著名网络作家爱潜水的乌贼（袁野）接受新华社记者采访时表示，中国网络文学能够在海外广泛流行，一方面在于作品构建出新奇有趣的世界；另一方面，亲情、友情、爱情是人类共有的情感，打动人心的作品自然能够打动不同国家的读者。 作者：李姝莛 殷家捷 宋芷蕙 余俊杰 金剑 新华社音视频部制作",
