    "content": "新华社贵阳7月30日电 题：“东纺西移”入黔来 织就家门口的幸福 新华社记者刘智强 织机哒哒作响，纱线来回穿梭。走进贵州省毕节瑞晶纺织科技有限责任公司的生产车间，只见33岁的胡倩用手指捏着针织袖子边缘，正一针一针地往缝盘机上套。不一会儿，她便完成了一件针织衫的套口工序。虽然入职才第5个月，但胡倩的操作已然熟练，如今每月稳定到手6000多元收入。 胡倩告诉记者，过去，她曾长期在浙江宁波打工，前几年回到家乡毕节结婚生子。“这两年孩子大了一些，想出去打工又放心不下孩子，心里总是犯愁。”胡倩说，今年3月得知自家附近新建的纺…"
