    "content": "5月8日，工作人员在美国纽约一家超市整理货物。新华社记者 张凤国 摄 新华社纽约7月30日电（记者刘亚南）美国商务部30日公布的初步数据显示，美国2026年第二季度经济环比按年率计算增长1.5%，低于第一季度的2.1%和市场预期。 美国商务部表示，消费支出、投资和出口对二季度国内生产总值（GDP）增长作出贡献，但部分被政府支出减少抵消。按照GDP核算方法，进口增长会拉低经济增速，而二季度美国进口仍保持增长。 数据显示，当季占美国经济总量约70%的个人消费支出同比增长3.2%，显著高于一季度的0.5%。反映企业投资状…"
