    "pub_date": "2026-07-30 23:23:16",
    "author": "袁波",
    "description": "新华社成都7月30日电（记者袁波）根据当前防汛形势，四川省防汛抗旱指挥部研究决定7月30日17时启动四级防汛应急响应，同时四川省水利厅将洪水灾害防御四级响应升级为三级响应。 7月30日，四川省气象台升级发布暴雨黄色预警，7月30日20时到31日20时，广元、绵阳、德阳、成都、眉山5市，雅安、乐山2市北部的部分地方有暴雨，局部大暴雨。 记者从四川省水利厅了解到，经多部门会商研判，四川盆地西部山区发生山洪地质灾害风险较高，大渡河、嘉陵江可能…",
    "content": "新华社成都7月30日电（记者袁波）根据当前防汛形势，四川省防汛抗旱指挥部研究决定7月30日17时启动四级防汛应急响应，同时四川省水利厅将洪水灾害防御四级响应升级为三级响应。 7月30日，四川省气象台升级发布暴雨黄色预警，7月30日20时到31日20时，广元、绵阳、德阳、成都、眉山5市，雅安、乐山2市北部的部分地方有暴雨，局部大暴雨。 记者从四川省水利厅了解到，经多部门会商研判，四川盆地西部山区发生山洪地质灾害风险较高，大渡河、嘉陵江可能发生明显涨水过程，青衣江、岷江、涪江、沱江可能发生超警洪水。四川省防汛抗旱指挥部…"
