    "description": "冷兵器时代，叮咣叮咣的干架，和游戏还不太像，主要是为了避免血腥程度，游戏做了大量的夸张，各种特效真实战斗根本不可能有。 自从无人机进入战场，并称为决胜的关键力量时，发现打游戏和打战，真的越来越像了 哪些在地下室、掩体里操作无人机的“战士”不少就是游戏爱好者，这些年轻人熟练的操作 FPV 寻找目标，然后投弹，跟打游戏真的没什么区别啦",
