    "title": "活力中国调研行丨浙江人形机器人加速多场景应用",
    "link": "http://www.news.cn/20260730/6ea48f671df24a9c8bf48b180ae9c45e/c.html",
    "pub_date": "2026-07-30 23:03:10",
