    "description": "新华社香港7月30日电（谢妞）“维港纽带创科基金”签约仪式30日在港举行，首批9个沪港科创储备项目正式亮相。这是香港特区政府“创科创投基金”优化计划下特区政府与内地机构合作签约设立的首只基金。 “维港纽带创科基金”总规模6亿港元，由上海国有资本投资有限公司作为基石投资人，中信资本担任管理人，交银国际、太平资管（香港）担任共同管理人，香港特区政府“创科创投基金”以有限合伙人身份参与出资。 香港特区政府于2017年成立20亿港元“创科创投基…",
    "content": "新华社香港7月30日电（谢妞）“维港纽带创科基金”签约仪式30日在港举行，首批9个沪港科创储备项目正式亮相。这是香港特区政府“创科创投基金”优化计划下特区政府与内地机构合作签约设立的首只基金。 “维港纽带创科基金”总规模6亿港元，由上海国有资本投资有限公司作为基石投资人，中信资本担任管理人，交银国际、太平资管（香港）担任共同管理人，香港特区政府“创科创投基金”以有限合伙人身份参与出资。 香港特区政府于2017年成立20亿港元“创科创投基金”，旨在鼓励更多风险投资（风投）基金共同投资于本地创新及科技（创科）初创企业。…"
