    "description": "新华社乌鲁木齐7月30日电（郝玉、杨生蕾）30日，G30连霍高速公路星星峡至哈密段、哈密至吐峪沟段完成改扩建，全线通车运营，进出新疆“咽喉”路段由过去双向四车道拓宽为双向八车道，进出疆高速通行能力翻倍。 G30连霍高速是国家高速公路网中重要的东西横向主干线，也是进出新疆高速公路三大通道之一。星哈段、哈吐段分别位于新疆哈密市、吐鲁番市境内，是进出新疆重要的“咽喉”路段。该路段投用多年，随着交通量逐年攀升，高峰时段通行不畅，日渐成为制约区域…",
    "content": "新华社乌鲁木齐7月30日电（郝玉、杨生蕾）30日，G30连霍高速公路星星峡至哈密段、哈密至吐峪沟段完成改扩建，全线通车运营，进出新疆“咽喉”路段由过去双向四车道拓宽为双向八车道，进出疆高速通行能力翻倍。 G30连霍高速是国家高速公路网中重要的东西横向主干线，也是进出新疆高速公路三大通道之一。星哈段、哈吐段分别位于新疆哈密市、吐鲁番市境内，是进出新疆重要的“咽喉”路段。该路段投用多年，随着交通量逐年攀升，高峰时段通行不畅，日渐成为制约区域发展的“瓶颈”。 2023年，星哈段、哈吐段改扩建工程启动，项目总里程为537公…"
