    "content": "7月27日，在墨西哥瓦哈卡州瓦哈卡市盖拉盖查音乐厅，演员表演传统舞蹈。新华社记者 柳文惠 摄 新华社墨西哥瓦哈卡7月30日电 行走拉美手记｜7月，赴一场盖拉盖查之约 新华社记者翟淑睿 柳文惠 7月最后一个星期一，午后的阳光洒向墨西哥南部城市瓦哈卡。福尔廷山顶上，可容纳万余人的盖拉盖查剧场座无虚席，“山上的星期一”庆典在欢呼声中拉开帷幕。 五彩丝带装点着街巷，悠扬的铜管乐不时传来。偶然转过一个街角，便能遇见身着民族服饰的舞团，舞步、乐声与欢笑交织，引得人们驻足观赏，整座城市仿佛是一座没有围墙的剧场。 “盖拉盖查”一词…"
