    "content": "30/07/2026 - 16:18 法新社30日基辅消息，乌克兰经历又一个轰炸之夜，共有8人遇难，包括一家6口。周四，总统泽连斯基再次敦促盟友提供反导弹系统。 据警方和当地当局称，在乌克兰中部“克里-维里格”附近一个村庄的一栋民宅遭弹道导弹袭击，一家六口，三名成人和三名儿童不幸遇难。 据当地当局称，基辅有1人遇难，另有2人受伤。当晚，法新社一名女记者在首都响起防空警报后听到了数次爆炸声，许多居民涌入地铁。 据报，俄罗斯当夜向乌克兰发射了74枚导弹和284架无人机，造成至少8人死亡，袭击目标主要集中在与波兰接壤的西…"
