    "content": "30/07/2026 - 16:28 俄罗斯电商巨头野莓（ Wildberries） 表示两周以来持续成为乌克兰袭击目标。其两座仓库，在周四凌晨再遭乌方无人机袭击。当地政府和该公司均证实了这一消息。 俄罗斯西部的奔萨州（Penza）州长梅利尼琴科（Oleg Melnitchenko）表示，一架无人机的袭击引发当地一座野莓（Wildberries）仓库起火，造成1人受伤，超过200名员工被疏散。 野莓公司还称，距离莫斯科以东约1100公里，位于萨拉普尔（Sarapoul）的仓库，当晚也遭乌克兰无人机袭击，并发生火灾。…"
