    "content": "新华社浙江嵊州7月30日电（记者潘毅）30日，名将柯洁九段在第六届“嵊州杯”中国王中王围棋争霸赛决赛中逆势翻盘，“绝杀”党毅飞九段，再度问鼎。 曾在2020年第二届王中王赛夺冠的柯洁此前一度远离赛场，但去年9月在棋圣战中实现三连冠后，柯洁的状态明显回升。本届赛事，柯洁一路连胜廖元赫九段、王星昊九段和上届冠军李轩豪九段，以胜者组头名率先闯入决赛。 决赛中面对从败者组“复活”的党毅飞，柯洁执黑率先对左上角的白棋发起试探性攻击。党毅飞则稳扎稳打不露破绽。行至百手，双方的胜率仍基本维持五五开，但黑棋隐约形成了中腹到右下的一…"
