    "content": "新华社拉萨7月30日电（记者普布次仁）西藏开投曲孜卡水电站30日在澜沧江畔举行开工仪式，进入全面建设阶段。项目总投资58.95亿元，装机容量40.5万千瓦。 西藏开投曲孜卡水电公司党委副书记、总经理别必雄介绍，项目建设总工期54个月，电站多年平均发电量可达18.69亿千瓦时。电站水库枢纽工程由挡水、泄洪、引水发电建筑物组成，大坝最大坝高79.5米、总长411米，具备日调节能力。 澜沧江水能资源充沛，是澜沧江上游（西藏段）清洁能源基地的重要组成部分。据了解，曲孜卡水电站建成投产后，每年可节约标准煤约56万吨，减少二氧…"
