    "content": "新华社耶路撒冷7月30日电（记者庞昕熠 王卓伦）《以色列时报》30日援引以方官员的消息报道说，巴勒斯坦伊斯兰抵抗运动（哈马斯）与斡旋方目前在埃及首都开罗举行的谈判已就解除武装问题“取得进展”。 报道称，有关各方正在推进一项路线图。该路线图提出了一条“平衡且务实”的路径，包括在加沙地带解除所有武装、分阶段移交职责，最终将所有权力移交给巴勒斯坦技术官僚政府。 报道援引以方官员的话说，这一安排“不会对某些武器或人员作出例外规定”；该路线图制定了拆除所有地道、武器储存设施以及武器生产设施的程序。加沙地带的“所有武器”都将在…"
