    "content": "新华社柏林7月30日电（记者车云龙）德国联邦统计局30日公布的初步数据显示，由于政府临时燃油税减免措施到期，德国7月能源价格再次大幅上涨，推动当月通胀率升至2.8%，明显高于6月的2.3%。 德国联邦统计局表示，7月德国能源价格同比上涨8.3%，涨幅高于5月的6.6%和6月的3.4%。 分析人士指出，能源价格再次明显上涨与政府临时燃油税减免措施到期有关。自5月1日起，德国汽油和柴油税每升下调约17欧分，为期两个月。该措施在一定程度上抑制燃油价格上涨。 德国经济专家委员会此前发布春季经济预测报告指出，受能源价格上涨影…"
