    "content": "新华社北京7月30日电 题：读懂好感度攀升背后的中国魅力 辛识平 美国皮尤研究中心近期发布的一项调查结果显示，在接受调查的36个国家和地区中，对中国的好感度超过对美国的好感度。此前，多家国际民调机构调查显示，越来越多国际民众对中国怀有更大兴趣、更好印象、更强认同。不断上扬的好感度曲线，诠释着大势所趋、人心所向，折射出国际社会对中国发展成就、治理能力、开放姿态与合作理念的充分肯定。 好感中，有对气象万千的中国风貌的向往。这个夏天，不少欧洲游客扎堆涌入中国。“对一个欧洲人来说，在当代中国游历是一种充满奇特反差感的体验”…"
