    "description": "中新网7月30日电 据应急管理部微信公众号消息，7月30日上午，国家防总办公室、应急管理部继续组织中国气象局、水利部、自然资源部、住房城乡建设部、工业和信息化部、交通运输部等部门联合会商，研判强降雨发展趋势，部署重点地区防汛工作。国家防总、应急管理部维持针对广东、四川、甘肃的防汛四级应急响应和针对内蒙古、新疆、新疆生产建设兵团的抗旱四级应急响应，增派1个防汛工作组赴四川协助指导防汛工作，1个抗旱工作组赴内蒙古、新疆、新疆生产建设兵团协助…",
    "content": "中新网7月30日电 据应急管理部微信公众号消息，7月30日上午，国家防总办公室、应急管理部继续组织中国气象局、水利部、自然资源部、住房城乡建设部、工业和信息化部、交通运输部等部门联合会商，研判强降雨发展趋势，部署重点地区防汛工作。国家防总、应急管理部维持针对广东、四川、甘肃的防汛四级应急响应和针对内蒙古、新疆、新疆生产建设兵团的抗旱四级应急响应，增派1个防汛工作组赴四川协助指导防汛工作，1个抗旱工作组赴内蒙古、新疆、新疆生产建设兵团协助指导抗旱减灾工作，前期派出的工作组继续在广东指导防汛救灾工作。"
